from collections import Counter
def solve(I):
    H,W=len(I),len(I[0])
    bg=Counter(x for r in I for x in r).most_common(1)[0][0]
    seen=[[False]*W for _ in range(H)]
    comps=[]
    for r in range(H):
        for c in range(W):
            if I[r][c]!=bg and not seen[r][c]:
                st=[(r,c)]; cells=set()
                while st:
                    y,x=st.pop()
                    if (y,x) in cells: continue
                    cells.add((y,x))
                    for dy in(-1,0,1):
                        for dx in(-1,0,1):
                            ny,nx=y+dy,x+dx
                            if 0<=ny<H and 0<=nx<W and I[ny][nx]!=bg and (ny,nx) not in cells:
                                st.append((ny,nx))
                # re-split into mono-color subcomps? use: majority color = shape color, minority cell = marker
                cnt=Counter(I[y][x] for y,x in cells)
                main=cnt.most_common(1)[0][0]
                others=[k for k in cnt if k!=main]
                if len(cells)>1:
                    objs.append(cells,main,others)
                else:
                    seeds.append((r,c,I[r][c]))
    # rebuild cleanly
    objs=[]; seeds=[]
    seen=[[False]*W for _ in range(H)]
    for r in range(H):
        for c in range(W):
            if I[r][c]!=bg and not seen[r][c]:
                st=[(r,c)]; cells=set(); cur=I[r][c]
                while st:
                    y,x=st.pop()
                    if (y,x) in cells: continue
                    cells.add((y,x))
                    for dy in(-1,0,1):
                        for dx in(-1,0,1):
                            ny,nx=y+dy,x+dx
                            if 0<=ny<H and 0<=nx<W and I[ny][nx]==cur and (ny,nx) not in cells:
                                st.append((ny,nx))
                cnt=Counter(I[y][x] for y,x in cells)
                if len(cells)==1: seeds.append((r,c,cur))
                elif len(cnt)==1: objs.append(('single '+str(cur),cells))
                else:
                    main=[k for k,v in cnt.items() if v==max(cnt.values())][0]
                    objs.append((main,cells,[k for k in cnt if k!=main][0]))
    out=[[bg]*W for _ in range(H)]
    for name,cells in objs:
        if name.startswith('single'): continue
        mcol=[k for k in cnt if k!=main][0]
        mcells=[(y,x) for y,x in cells if I[y][x]==mcol]
        assert len(mcells)==1
        my,mx=mcells[0]
        ys=[y for y,_ in cells]; xs=[x for _,x in cells]
        for sy,sx,_ in seeds:
            off_y,sy_=sy-my; off_x,sx_=sx-mx
            for y,x in cells:
                ny,nx=y-off_y,x-off_x
                if 0<=ny<H and 0<=nx<W: out[ny][nx]=I[y][x]
    return out
